-- Separate a completed empty interface walk from an unavailable/legacy empty result.
ALTER TABLE network_devices ADD COLUMN IF NOT EXISTS interfaces_observed boolean NOT NULL DEFAULT false;
UPDATE network_devices SET interfaces_observed=true
WHERE NOT interfaces_observed AND jsonb_typeof(interfaces)='array' AND jsonb_array_length(interfaces)>0;

CREATE OR REPLACE FUNCTION network_trusted_identity(p_value text)
RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
  SELECT CASE
    WHEN normalized IS NULL OR normalized = '' THEN NULL
    WHEN normalized IN ('unknown','n/a','na','not available','not applicable','not set','unassigned','default','none','null','0','undefined','-') THEN NULL
    WHEN compact <> '' AND compact !~ '[1-9a-z]' THEN NULL
    ELSE normalized
  END
  FROM (SELECT lower(btrim(p_value)) AS normalized,
               regexp_replace(lower(btrim(p_value)), '[-:.[:space:]]', '', 'g') AS compact) value
$$;

CREATE OR REPLACE FUNCTION ingest_network_metric_batch(p_agent_id uuid,p_company_id uuid,p_batch jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE n bigint; inserted integer; dev jsonb; d_id uuid; old_status text; new_status text; v_scope uuid; identity_kind text; identity_value text; trusted_engine_value text; current_device network_devices%ROWTYPE; observed timestamptz;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM registered_agents WHERE id=p_agent_id AND company_id=p_company_id AND agent_kind='network' AND status<>'Revoked') THEN RAISE EXCEPTION 'AGENT_SCOPE'; END IF;
 n:=(p_batch->>'sequence')::bigint;
 INSERT INTO network_agent_batches(agent_id,company_id,sequence,collected_at,payload) VALUES(p_agent_id,p_company_id,n,(p_batch->>'collected_at')::timestamptz,p_batch) ON CONFLICT(agent_id,sequence) DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT; IF inserted=0 THEN RETURN jsonb_build_object('status','duplicate','sequence',n); END IF;
 FOR dev IN SELECT value FROM jsonb_array_elements(p_batch->'devices') LOOP
   v_scope:=NULL; identity_kind:=NULL; identity_value:=NULL; trusted_engine_value:=network_trusted_identity(dev->>'engine_id'); observed:=(dev->>'observed_at')::timestamptz;
   SELECT NULLIF(configured->>'network_scope_id','')::uuid INTO v_scope FROM network_agent_configurations c, LATERAL jsonb_array_elements(COALESCE(c.configuration->'networks','[]'::jsonb)) configured
   WHERE c.agent_id=p_agent_id AND c.company_id=p_company_id AND c.enabled AND configured->>'id'=dev->>'network_id' AND COALESCE((configured->>'enabled')::boolean,false)
     AND (dev->>'ip_address')::inet <<= (configured->>'cidr')::cidr AND NOT COALESCE(configured->'excluded_ips','[]'::jsonb) @> jsonb_build_array(dev->>'ip_address')
     AND (NULLIF(configured->>'network_scope_id','') IS NULL OR EXISTS(SELECT 1 FROM network_physical_scopes ps WHERE ps.id=(configured->>'network_scope_id')::uuid AND ps.company_id=p_company_id));
   IF NOT FOUND THEN RAISE EXCEPTION 'AGENT_SCOPE'; END IF;
   IF network_trusted_identity(dev->>'serial_number') IS NOT NULL THEN identity_kind:='serial'; identity_value:=network_trusted_identity(dev->>'serial_number');
   ELSIF network_trusted_identity(dev->>'engine_id') IS NOT NULL THEN identity_kind:='engine_id'; identity_value:=network_trusted_identity(dev->>'engine_id'); END IF;
   d_id:=NULL; old_status:=NULL;
   IF v_scope IS NOT NULL THEN SELECT device_id INTO d_id FROM network_agent_device_bindings WHERE agent_id=p_agent_id AND network_id=(dev->>'network_id')::uuid AND device_uid=dev->>'device_uid'; IF d_id IS NOT NULL THEN SELECT * INTO current_device FROM network_devices WHERE id=d_id AND company_id=p_company_id AND network_scope_id=v_scope; IF FOUND THEN identity_kind:=current_device.trusted_identity_kind; identity_value:=current_device.trusted_identity_value; ELSE d_id:=NULL; END IF; END IF; END IF;
   IF d_id IS NOT NULL THEN old_status:=(SELECT status FROM network_devices WHERE id=d_id); END IF;
   IF v_scope IS NOT NULL AND identity_value IS NOT NULL THEN
     PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_scope::text||':'||identity_kind||':'||identity_value,0));
     -- Recheck serial/engine evidence only after the serial lock. Concurrent first observations
     -- cannot both conclude that the serial is unused while one insert is still uncommitted.
     IF identity_kind='serial' AND trusted_engine_value IS NOT NULL THEN
       SELECT d.* INTO current_device FROM network_devices d WHERE d.company_id=p_company_id AND d.network_scope_id=v_scope AND d.trusted_identity_kind='serial' AND d.trusted_identity_value=identity_value FOR UPDATE;
       IF FOUND AND network_trusted_identity(current_device.engine_id) IS NOT NULL AND network_trusted_identity(current_device.engine_id)<>trusted_engine_value THEN
         identity_kind:='engine_id'; identity_value:=trusted_engine_value; d_id:=NULL; old_status:=NULL;
         PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_scope::text||':'||identity_kind||':'||identity_value,0));
       END IF;
     END IF;
     SELECT d.* INTO current_device FROM network_devices d WHERE d.company_id=p_company_id AND d.network_scope_id=v_scope AND d.trusted_identity_kind=identity_kind AND d.trusted_identity_value=identity_value FOR UPDATE;
     IF FOUND THEN
       d_id:=current_device.id; old_status:=current_device.status;
       UPDATE network_devices SET agent_id=CASE WHEN observed>=last_poll_at THEN p_agent_id ELSE agent_id END,monitoring_source='agent_snmp',ip_address=CASE WHEN observed>=last_poll_at THEN dev->>'ip_address' ELSE ip_address END,device_name=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN dev->>'device_name' ELSE device_name END,device_type=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(dev->>'device_type','Outro') ELSE device_type END,result=CASE WHEN observed>=last_poll_at THEN dev->>'result' ELSE result END,last_poll_at=GREATEST(last_poll_at,observed),last_success_at=GREATEST(last_success_at,CASE WHEN dev->>'result' IN ('success','partial') THEN observed END),status=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN 'Online' WHEN observed>=last_poll_at AND dev->>'result'='timeout' AND consecutive_failures>=2 THEN 'Sem resposta SNMP' WHEN observed>=last_poll_at THEN 'Atencao' ELSE status END,consecutive_failures=CASE WHEN observed>=last_poll_at AND dev->>'result'='timeout' THEN consecutive_failures+1 WHEN observed>=last_poll_at THEN 0 ELSE consecutive_failures END,sys_object_id=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(NULLIF(dev->>'sys_object_id',''),sys_object_id) ELSE sys_object_id END,sys_description=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(NULLIF(dev->>'sys_description',''),sys_description) ELSE sys_description END,sys_contact=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(NULLIF(dev->>'sys_contact',''),sys_contact) ELSE sys_contact END,snmp_uptime=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(NULLIF(dev->>'uptime_seconds','')::bigint,snmp_uptime) ELSE snmp_uptime END,response_time_ms=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(NULLIF(dev->>'response_time_ms','')::double precision,response_time_ms) ELSE response_time_ms END,manufacturer=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(NULLIF(dev->>'manufacturer',''),manufacturer) ELSE manufacturer END,model=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(NULLIF(dev->>'model',''),model) ELSE model END,serial_number=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(NULLIF(dev->>'serial_number',''),serial_number) ELSE serial_number END,firmware_version=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(NULLIF(dev->>'firmware_version',''),firmware_version) ELSE firmware_version END,location=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(NULLIF(dev->>'location',''),location) ELSE location END,engine_id=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') THEN COALESCE(CASE WHEN network_trusted_identity(dev->>'engine_id') IS NOT NULL THEN dev->>'engine_id' END,engine_id) ELSE engine_id END,interfaces=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') AND (COALESCE((dev->>'interfaces_observed')::boolean,false) OR (dev->'interfaces_observed' IS NULL AND jsonb_array_length(COALESCE(dev->'interfaces','[]'::jsonb))>0)) THEN COALESCE(dev->'interfaces','[]') ELSE interfaces END,interfaces_observed=CASE WHEN observed>=last_poll_at AND dev->>'result' IN ('success','partial') AND dev->'interfaces_observed' IS NOT NULL THEN (dev->>'interfaces_observed')::boolean WHEN observed>=last_poll_at AND jsonb_array_length(COALESCE(dev->'interfaces','[]'::jsonb))>0 THEN true ELSE interfaces_observed END,updated_at=now(),last_updated=now() WHERE id=d_id RETURNING status INTO new_status;
     END IF;
   END IF;
   IF d_id IS NULL THEN
     SELECT status INTO old_status FROM network_devices WHERE company_id=p_company_id AND network_id=(dev->>'network_id')::uuid AND device_uid=dev->>'device_uid';
     INSERT INTO network_devices(company_id,network_id,agent_id,device_uid,network_scope_id,trusted_identity_kind,trusted_identity_value,monitoring_source,ip_address,device_name,device_type,status,result,last_poll_at,last_success_at,sys_object_id,sys_description,snmp_uptime,response_time_ms,manufacturer,model,serial_number,firmware_version,location,engine_id,sys_contact,interfaces,interfaces_observed,consecutive_failures)
     VALUES(p_company_id,(dev->>'network_id')::uuid,p_agent_id,dev->>'device_uid',v_scope,identity_kind,identity_value,'agent_snmp',(dev->>'ip_address')::inet,dev->>'device_name',COALESCE(dev->>'device_type','Outro'),CASE WHEN dev->>'result' IN ('success','partial') THEN 'Online' ELSE 'Atencao' END,dev->>'result',observed,CASE WHEN dev->>'result' IN ('success','partial') THEN observed END,dev->>'sys_object_id',dev->>'sys_description',NULLIF(dev->>'uptime_seconds','')::bigint,NULLIF(dev->>'response_time_ms','')::double precision,dev->>'manufacturer',dev->>'model',dev->>'serial_number',dev->>'firmware_version',dev->>'location',dev->>'engine_id',dev->>'sys_contact',COALESCE(dev->'interfaces','[]'),COALESCE((dev->>'interfaces_observed')::boolean,jsonb_array_length(COALESCE(dev->'interfaces','[]'::jsonb))>0),CASE WHEN dev->>'result'='timeout' THEN 1 ELSE 0 END)
     ON CONFLICT(company_id,network_id,device_uid) DO UPDATE SET monitoring_source='agent_snmp',network_scope_id=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at THEN EXCLUDED.network_scope_id ELSE network_devices.network_scope_id END,trusted_identity_kind=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at THEN COALESCE(EXCLUDED.trusted_identity_kind,network_devices.trusted_identity_kind) ELSE network_devices.trusted_identity_kind END,trusted_identity_value=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at THEN COALESCE(EXCLUDED.trusted_identity_value,network_devices.trusted_identity_value) ELSE network_devices.trusted_identity_value END,ip_address=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at THEN EXCLUDED.ip_address ELSE network_devices.ip_address END,device_name=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN EXCLUDED.device_name ELSE network_devices.device_name END,device_type=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN EXCLUDED.device_type ELSE network_devices.device_type END,result=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at THEN EXCLUDED.result ELSE network_devices.result END,last_poll_at=GREATEST(EXCLUDED.last_poll_at,network_devices.last_poll_at),last_success_at=GREATEST(EXCLUDED.last_success_at,network_devices.last_success_at),status=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN 'Online' WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result='timeout' AND network_devices.consecutive_failures>=2 THEN 'Sem resposta SNMP' WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at THEN 'Atencao' ELSE network_devices.status END,consecutive_failures=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result='timeout' THEN network_devices.consecutive_failures+1 WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at THEN 0 ELSE network_devices.consecutive_failures END,sys_object_id=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(EXCLUDED.sys_object_id,network_devices.sys_object_id) ELSE network_devices.sys_object_id END,sys_description=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(EXCLUDED.sys_description,network_devices.sys_description) ELSE network_devices.sys_description END,sys_contact=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(EXCLUDED.sys_contact,network_devices.sys_contact) ELSE network_devices.sys_contact END,snmp_uptime=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(EXCLUDED.snmp_uptime,network_devices.snmp_uptime) ELSE network_devices.snmp_uptime END,response_time_ms=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(EXCLUDED.response_time_ms,network_devices.response_time_ms) ELSE network_devices.response_time_ms END,manufacturer=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(EXCLUDED.manufacturer,network_devices.manufacturer) ELSE network_devices.manufacturer END,model=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(EXCLUDED.model,network_devices.model) ELSE network_devices.model END,serial_number=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(EXCLUDED.serial_number,network_devices.serial_number) ELSE network_devices.serial_number END,firmware_version=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(EXCLUDED.firmware_version,network_devices.firmware_version) ELSE network_devices.firmware_version END,location=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(EXCLUDED.location,network_devices.location) ELSE network_devices.location END,engine_id=CASE WHEN EXCLUDED.last_poll_at>=network_devices.last_poll_at AND EXCLUDED.result IN ('success','partial') THEN COALESCE(CASE WHEN network_trusted_identity(EXCLUDED.engine_id) IS NOT NULL THEN EXCLUDED.engine_id END,network_devices.engine_id) ELSE network_devices.engine_id END,interfaces=CASE WHEN EXCLUDED.result IN ('success','partial') AND EXCLUDED.last_poll_at>=network_devices.last_poll_at AND (EXCLUDED.interfaces_observed OR jsonb_array_length(EXCLUDED.interfaces)>0) THEN EXCLUDED.interfaces ELSE network_devices.interfaces END,interfaces_observed=CASE WHEN EXCLUDED.result IN ('success','partial') AND EXCLUDED.last_poll_at>=network_devices.last_poll_at THEN EXCLUDED.interfaces_observed ELSE network_devices.interfaces_observed END,updated_at=now(),last_updated=now() RETURNING id,status INTO d_id,new_status;
   END IF;
   IF v_scope IS NOT NULL AND identity_value IS NOT NULL THEN INSERT INTO network_agent_device_bindings(agent_id,network_id,device_uid,company_id,device_id) VALUES(p_agent_id,(dev->>'network_id')::uuid,dev->>'device_uid',p_company_id,d_id) ON CONFLICT(agent_id,network_id,device_uid) DO UPDATE SET device_id=EXCLUDED.device_id,company_id=EXCLUDED.company_id; END IF;
   INSERT INTO network_device_samples(device_id,company_id,agent_id,sequence,observed_at,result,payload) VALUES(d_id,p_company_id,p_agent_id,n,observed,dev->>'result',dev) ON CONFLICT DO NOTHING;
   INSERT INTO network_status_history(company_id,network_device_id,device_name,device_type,ip_address,status,collected_at) VALUES(p_company_id,d_id,dev->>'device_name',dev->>'device_type',dev->>'ip_address',CASE WHEN dev->>'result' IN ('success','partial') THEN 'Online' ELSE 'Atencao' END,observed);
   INSERT INTO asset_profiles(company_id,source_type,source_id,asset_type,display_name,manufacturer,model,serial_number,firmware_version,location,auto_data,last_synced_at)
   SELECT d.company_id,'network_device',d.id,'network',d.device_name,d.manufacturer,d.model,d.serial_number,d.firmware_version,d.location,jsonb_build_object('ip_address',d.ip_address,'result',d.result,'last_poll_at',d.last_poll_at),now() FROM network_devices d WHERE d.id=d_id
   ON CONFLICT(company_id,source_type,source_id) DO UPDATE SET manufacturer=CASE WHEN 'manufacturer'=ANY(COALESCE(asset_profiles.manual_override_fields,'{}')) THEN asset_profiles.manufacturer ELSE COALESCE(EXCLUDED.manufacturer,asset_profiles.manufacturer) END,model=CASE WHEN 'model'=ANY(COALESCE(asset_profiles.manual_override_fields,'{}')) THEN asset_profiles.model ELSE COALESCE(EXCLUDED.model,asset_profiles.model) END,serial_number=CASE WHEN 'serial_number'=ANY(COALESCE(asset_profiles.manual_override_fields,'{}')) THEN asset_profiles.serial_number ELSE COALESCE(EXCLUDED.serial_number,asset_profiles.serial_number) END,firmware_version=CASE WHEN 'firmware_version'=ANY(COALESCE(asset_profiles.manual_override_fields,'{}')) THEN asset_profiles.firmware_version ELSE COALESCE(EXCLUDED.firmware_version,asset_profiles.firmware_version) END,location=CASE WHEN 'location'=ANY(COALESCE(asset_profiles.manual_override_fields,'{}')) THEN asset_profiles.location ELSE COALESCE(EXCLUDED.location,asset_profiles.location) END,auto_data=asset_profiles.auto_data||EXCLUDED.auto_data,last_synced_at=now();
   IF old_status IS DISTINCT FROM new_status THEN INSERT INTO monitoring_events(company_id,source,entity_name,entity_type,previous_status,current_status,severity,message,metadata) VALUES(p_company_id,'network',dev->>'device_name','network_device',old_status,new_status,CASE WHEN new_status='Online' THEN 'info' ELSE 'warning' END,CASE WHEN new_status='Online' THEN 'Equipamento respondeu via SNMP' ELSE 'Falha de consulta SNMP' END,jsonb_build_object('network_device_id',d_id,'agent_id',p_agent_id,'result',dev->>'result')); END IF;
 END LOOP; RETURN jsonb_build_object('status','accepted','sequence',n);
END $$;
